vec3 v1 = c - a;
vec3 v2 = p - a;

float d00 = std::dot(v0, v0);
float d01 = std::dot(v0, v1);
float d11 = std::dot(v1, v1);
float d20 = std::dot(v2, v0);
float d21 = std::dot(v2, v1);

float denom = d00 * d11 - d01 * d01;
float v = (d11 * d20 - d01 * d21) / denom;
float w = (d00 * d21 - d01 * d20) / denom;
float u = 1.0f - v - w;

return vec3(u, v, w);
// END_CODE

